// 侧栏里用加粗版，和侧栏其他图标一致；网格和检查器里用普通版。
var (
	folderIconsRegular = parseIcons(folderIconSource, false)
	folderIconsSidebar = parseIcons(folderIconSource, true)
)

// 侧栏行按名字取图标时，这个前缀后面跟文件夹图标编号。
const folderIconPrefix = "folder-icon:"

const (
	folderIconColumns = 8
	folderIconCell    = 30
	folderIconGlyph   = 16
	folderIconGap     = 2
)

// 不认识的编号（比如新版加的图标在旧版里打开）按默认文件夹图标显示。
func folderIconID(id string) string {
	if !slices.Contains(folderIconIDs, id) {
		return "folder"
	}
	return id
}

func folderIcon(c *ui.Context, id string) ui.Element {
	return ui.Icon(c, folderIconsRegular[folderIconID(id)]).Size(iconSize, iconSize)
}

func folderSidebarIcon(c *ui.Context, id string) ui.Element {
	return ui.Icon(c, folderIconsSidebar[folderIconID(id)]).Size(iconSize, iconSize)
}

func (a *App) folderIconName(id string) string {
	return a.T("folder_icon_" + folderIconID(id))
}

// 文件夹图标网格：第一格是默认文件夹；选中的铺品牌色浅底、图标换品牌色，外加一圈很浅的品牌色细边；点了就收起。
func (a *App) folderIconGrid(c *ui.Context, icon *string, open *bool) {
	p := paletteFor(c.Theme())
	ids := append([]string{""}, folderIconIDs...)
	ui.Column(c.Key("folder-icon-grid")).Gap(folderIconGap).Children(func() {
		for start := 0; start < len(ids); start += folderIconColumns {
			ui.Row(c).Gap(folderIconGap).Children(func() {
				for _, id := range ids[start:min(start+folderIconColumns, len(ids))] {
					name := a.folderIconName(id)
					chosen := folderIconID(*icon) == folderIconID(id)
					cell := ui.ButtonBase(c.Key("icon-"+id)).Size(folderIconCell, folderIconCell).Shrink(0).Padding(0).Radius(radiusControl).
						Cursor(ui.CursorPointer).Justify(ui.Center).AlignItems(ui.Center).Label(name).Tooltip(name).Role(ui.RoleRadio).Checked(chosen)
					background, ring, ink := ui.Transparent, ui.Transparent, p.TextSecondary
					switch {
					case chosen:
						background, ring, ink = p.Accent.Alpha(themeValue(c, .12, .2)), p.Accent.Alpha(themeValue(c, .28, .4)), p.Accent
					case cell.Hovered():
						background, ink = p.Hover, p.Text
					}
					cell.Background(cell.AnimateColor("bg", background, motionColor)).Border(1, cell.AnimateColor("ring", ring, motionColor))
					cell.Children(func() {
						ui.Icon(c, folderIconsRegular[folderIconID(id)]).Size(folderIconGlyph, folderIconGlyph).TextColor(cell.AnimateColor("ink", ink, motionColor)).PassThrough()
					})
					if cell.Clicked() {
						*icon, *open = id, false
					}
				}
			})
		}
	})
}
